# ============================================================
# database.py — the structured exercise library.
#
# EVERY exercise below is drawn from a real, cited injury-prevention
# program's own published manual or protocol (see research_library.py
# for the full citations) — described here in this app's own words, not
# invented, and not copied verbatim from the source documents. Nothing
# here was generated by asking an LLM to "come up with ACL exercises."
#
# WHAT'S DELIBERATELY NOT HERE: Sportsmetrics-branded individual drills.
# The available sources describe Sportsmetrics' program STRUCTURE
# (double-leg jumps progressing to single-leg, multi-directional landing
# control) but not specific named exercises with step-by-step
# instructions, so nothing is attributed to it beyond that structural
# citation in research_library.py. Better to under-claim than invent
# choreography and attach a real citation to it.
#
# AGE GATING ON PLYOMETRICS: the PEP program's own manual explicitly
# instructs coaches to keep plyometrics double-leg, land-with-two-feet,
# and over a flat cone or line for athletes 12 and under, and to withhold
# single-leg plyometrics from young athletes until they show "substantial
# control." That's encoded directly below — single-leg jumping/hopping
# exercises exclude the 12-13 age range, with the reasoning in
# safety_notes, not silently applied.
# ============================================================

from dataclasses import dataclass, field
from typing import Literal

from app.exercises.research_library import FIFA_11_PLUS, FIFA_11_PLUS_KIDS, PEP_PROGRAM

Difficulty = Literal["beginner", "intermediate", "advanced"]

# The vocabulary a future ranking engine matches against LESS items and
# risk-factor measurements (see risk/less.py, risk/scoring.py). Kept
# small and tied to what this app actually measures, rather than a
# generic fitness taxonomy.
MovementTarget = Literal[
    "landing_control",       # soft-landing / overall plyometric control
    "frontal_knee_control",  # valgus, knee caving inward
    "knee_flexion",          # landing depth, stiff-landing prevention
    "trunk_control",         # trunk lean, upper-body stability on landing
    "symmetry",               # left/right balance
    "hip_strength",
    "hamstring_strength",
    "calf_ankle_strength",
    "core_stability",
    "balance",
    "deceleration",
]

Sport = Literal[
    "soccer", "basketball", "volleyball", "lacrosse", "field_hockey", "track_field", "other",
]
AgeRange = Literal["12-13", "14-15", "16-17", "18+"]
CompetitiveLevel = Literal[
    "recreational", "club", "high_school", "college", "elite_academy", "other",
]

ALL_AGE_RANGES: list[AgeRange] = ["12-13", "14-15", "16-17", "18+"]
NO_UNDER_14: list[AgeRange] = ["14-15", "16-17", "18+"]
JUMP_CUT_SPORTS: list[Sport] = [
    "soccer", "basketball", "volleyball", "lacrosse", "field_hockey", "track_field",
]
ALL_LEVELS: list[CompetitiveLevel] = [
    "recreational", "club", "high_school", "college", "elite_academy", "other",
]

SINGLE_LEG_PLYO_SAFETY_NOTE = (
    "The PEP program's own manual instructs coaches to keep plyometrics "
    "double-leg, landing with two feet, over a flat line or low cone, for "
    "athletes 12 and under, and to withhold single-leg plyometrics until an "
    "athlete demonstrates substantial control. This exercise is single-leg, "
    "so it is not shown for the 12-13 age range here."
)


@dataclass(frozen=True)
class Exercise:
    exercise_id: str
    exercise_name: str
    short_description: str
    instructions: list[str]          # ordered steps
    movement_targets: list[MovementTarget]
    difficulty: Difficulty
    equipment: str
    age_ranges: list[AgeRange]
    sports: list[Sport]
    competitive_levels: list[CompetitiveLevel]
    research_source: str             # the specific citation, from research_library.py
    source_program: str              # program_name, from research_library.py
    safety_notes: str
    video_or_animation_reference: str | None = field(default=None)


