EXERCISES_BY_ID: dict[str, Exercise] = {e.exercise_id: e for e in EXERCISES}


def exercises_for_target(target: MovementTarget) -> list[Exercise]:
    """All exercises whose movement_targets include the given target."""
    return [e for e in EXERCISES if target in e.movement_targets]
